import { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { useProjectsContext } from './projects-context.js';
import { newId, type Task } from './task-tree.js';
import styles from './ui.module.css';

const COLORS = ['#7c5cff', '#ff5c7a', '#2bb3ff', '#ffb020', '#22c55e', '#e05cff'];

/**
 * New project frame: name, description, color and optional starter areas
 * (one per line) so the project structure exists from the start.
 */
export function NewProjectPage() {
  const { createProject } = useProjectsContext();
  const navigate = useNavigate();
  const [name, setName] = useState('');
  const [description, setDescription] = useState('');
  const [color, setColor] = useState(COLORS[0]);
  const [areas, setAreas] = useState('');
  const [busy, setBusy] = useState(false);

  const submit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!name.trim()) return;
    setBusy(true);
    const tasks: Task[] = areas
      .split('\n')
      .map((a) => a.trim())
      .filter(Boolean)
      .map((title) => ({ id: newId(), title, description: '', done: false, subtasks: [] }));
    try {
      const created = await createProject({ name: name.trim(), description: description.trim(), color, tasks });
      navigate(`/projects/${created.id}`);
    } finally {
      setBusy(false);
    }
  };

  return (
    <div className={styles.pageNarrow}>
      <nav className={styles.breadcrumb}><Link to="/">Dashboard</Link> <span>›</span> <span>New project</span></nav>
      <h1 className={styles.pageTitle}>New project</h1>
      <form className={`${styles.card} ${styles.formStack}`} onSubmit={submit}>
        <label className={styles.field}>
          <span>Project name</span>
          <input autoFocus className={styles.input} placeholder="e.g. FPS" value={name} onChange={(e) => setName(e.target.value)} />
        </label>
        <label className={styles.field}>
          <span>Description <em>(optional)</em></span>
          <input className={styles.input} placeholder="What are you building?" value={description} onChange={(e) => setDescription(e.target.value)} />
        </label>
        <div className={styles.field}>
          <span>Color</span>
          <div className={styles.swatches}>
            {COLORS.map((c) => (
              <button type="button" key={c} aria-label={`Color ${c}`} className={`${styles.swatch} ${c === color ? styles.swatchActive : ''}`} style={{ background: c }} onClick={() => setColor(c)} />
            ))}
          </div>
        </div>
        <label className={styles.field}>
          <span>Starter areas <em>(optional, one per line)</em></span>
          <textarea className={styles.textarea} rows={4} placeholder={'Gun system\nMovement\nNetworking'} value={areas} onChange={(e) => setAreas(e.target.value)} />
        </label>
        <div className={styles.formButtons}>
          <Link to="/" className={styles.ghostBtn}>Cancel</Link>
          <button type="submit" className={styles.primaryBtn} disabled={!name.trim() || busy}>Create project</button>
        </div>
      </form>
    </div>
  );
}
